64	        this.periods = periods;
65	        this.settings = settings;
66	        this.audit = audit;
67	    }
68	
69	    @Transactional(readOnly = true)
70	    public List<Claim> list(String sheetId) {
71	        return claims.findBySheetIdOrderByListedDesc(sheetId);
72	    }
73	
74	    /** The status logs of the sheet's claims, each oldest first, by claim id. */
75	    @Transactional(readOnly = true)
76	    public Map<Long, List<ClaimLog>> logs(String sheetId) {
77	        Map<Long, List<ClaimLog>> byClaim = new HashMap<>();
78	        for (ClaimLog line : log.findBySheetIdOrderByIdAsc(sheetId)) {
79	            byClaim.computeIfAbsent(line.getClaimId(), k -> new ArrayList<>()).add(line);
80	        }
81	        return byClaim;
82	    }
83	
84	    /** A claim's status log, oldest first. */
85	    @Transactional(readOnly = true)
86	    public List<ClaimLog> logOf(long claimId) {
87	        return log.findByClaimIdOrderByIdAsc(claimId);
88	    }
89	
90	    /** The claims of the ids on the sheet in list order: the people in the order they were added,
91	     *  each person's claims newest first; ids not on the sheet are left out. */
92	    @Transactional(readOnly = true)
93	    public List<Long> inListOrder(String sheetId, Collection<Long> ids) {
94	        Set<Long> wanted = new HashSet<>(ids);
95	        Map<Long, Integer> personOrder = new HashMap<>();
96	        List<Person> theirs = people.findBySheetIdOrderByIdAsc(sheetId);
97	        for (int i = 0; i < theirs.size(); i++) {
98	            personOrder.put(theirs.get(i).getId(), i);
99	        }
100	        return claims.findBySheetIdOrderByListedDesc(sheetId).stream()
101	                .filter(c -> wanted.contains(c.getId()))
102	                .sorted(Comparator.comparingInt(c -> personOrder.getOrDefault(c.getPersonId(), Integer.MAX_VALUE)))
103	                .map(Claim::getId)
104	                .toList();
105	    }
106	
107	    /** Add a claim for a person on the sheet; a missing date takes the sheet's today. Refused
108	     *  (423) when the date is in a closed period, (422) when it is after the person's
109	     *  retirement date, and (422) when it is a correction (a negative amount) that does not name
110	     *  the number of a SETTLED claim of the same person. */
111	    @Transactional
112	    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
113	            String corrects) {
114	        Person person = people.findByIdAndSheetId(personId, sheetId)
115	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
116	        LocalDate on = date != null ? date : sheets.today(sheetId);
117	        refuseIfClosed(sheetId, on);
118	        refuseIfRetired(person, on);
119	        String corrected = correctedBy(sheetId, personId, amount, corrects);
120	        RollupService.Snapshot before = rollup.snapshot(sheetId);
121	        int terms = sheets.find(sheetId).map(s -> s.termsFor(person.gradeOn(on))).orElse(Sheet.DEFAULT_TERMS);
122	        Claim fresh = new Claim(sheetId, personId, amount, on, on.plusDays(terms), noteOf(note));
123	        fresh.setCorrects(corrected);
124	        // the sheet is locked (refuseIfClosed), so two claims added at once are listed one after the other
125	        fresh.setListed(claims.findLastListed(sheetId) + 1);
126	        Claim claim = claims.saveAndFlush(fresh);
127	        logStatus(user, person, claim);
128	        record("CLAIM_ADDED", user, person, claim);
129	        rollup.recordChanges(sheetId, user, before);
130	        return claim;
131	    }
132	
133	    /** Change a DRAFT claim's amount, date and note; a missing date takes the sheet's today.
134	     *  Refused (409) once the claim is no longer a DRAFT (an open claim is voided and a new one
135	     *  added instead), and (423) when its old or new date is in a closed period, and (422) when the new
136	     *  date is after the person's retirement date, or when it is a correction that does not name
137	     *  the number of a SETTLED claim of the same person. */
138	    @Transactional
139	    public Claim update(String sheetId, String user, long id, BigDecimal amount, LocalDate date, String note,
140	            String corrects) {
141	        Claim claim = claims.findForUpdate(id, sheetId)
142	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
143	        LocalDate on = date != null ? date : sheets.today(sheetId);
144	        refuseIfClosed(sheetId, claim.getDate());
145	        if (claim.getStatus() != ClaimStatus.DRAFT) {
146	            throw new ResponseStatusException(HttpStatus.CONFLICT,
147	                    "A " + claim.getStatus() + " claim cannot be edited");
148	        }
149	        refuseIfClosed(sheetId, on);
150	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
151	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
152	        refuseIfRetired(person, on);
153	        String corrected = correctedBy(sheetId, person.getId(), amount, corrects);
154	        RollupService.Snapshot before = rollup.snapshot(sheetId);
155	        claim.setAmount(amount);
156	        claim.setCorrects(corrected);
157	        claim.setDate(on);
158	        claim.setNote(noteOf(note));
159	        claims.flush();
160	        record("CLAIM_EDITED", user, person, claim);
161	        rollup.recordChanges(sheetId, user, before);
162	        return claim;
163	    }
164	
165	    /** Move a claim to a new status; a move its status does not allow is refused (409), as is
166	     *  settling by the user who opened the claim (403), settling a PENDING claim (409: it is
167	     *  approved or rejected instead), and any move of a claim dated in a closed period (423). A
168	     *  clerk settling a claim whose due is above the sheet's clerk limit sends it to PENDING. */
169	    @Transactional
170	    public Claim changeStatus(String sheetId, String user, long id, ClaimStatus to) {
171	        Claim claim = claims.findForUpdate(id, sheetId)
172	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
173	        refuseIfClosed(sheetId, claim.getDate());
174	        if (to == ClaimStatus.PENDING || (to == ClaimStatus.SETTLED && claim.getStatus() == ClaimStatus.PENDING)
175	                || !claim.getStatus().canMoveTo(to)) {
176	            throw new ResponseStatusException(HttpStatus.CONFLICT,
177	                    "A " + claim.getStatus() + " claim cannot become " + to);
178	        }
179	        if (to == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
180	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
181	                    "The user who opened a claim cannot settle it");
182	        }
183	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
184	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
185	        // a claim bound by a statement settles at its bound figure, its late charge frozen in
186	        BigDecimal settling = to == ClaimStatus.SETTLED ? shownDueOf(claim, person) : null;
187	        if (to == ClaimStatus.SETTLED && !settings.maySettle(sheetId, user, settling)) {
188	            // above the clerk limit: a steward approves or rejects it
189	            to = ClaimStatus.PENDING;
190	        }
191	        RollupService.Snapshot before = rollup.snapshot(sheetId);
192	        // a voided claim keeps its number (never reused), and the VOIDED record carries it
193	        String number = claim.getNumber();
194	        claim.setStatus(to);
195	        if (to == ClaimStatus.OPEN) {
196	            number = nextNumber(sheetId, claim.getDate());
197	            claim.setNumber(number);
198	            claim.setOpenedBy(user);
199	        } else if (to == ClaimStatus.SETTLED) {
200	            claim.setSettledDue(settling);
201	        }
202	        claims.flush();
203	        logStatus(user, person, claim);
204	        String event = switch (to) {
205	            case OPEN -> "CLAIM_OPENED";
206	            case PENDING -> "CLAIM_PENDING";
207	            case SETTLED -> "CLAIM_SETTLED";
208	            case VOID -> "CLAIM_VOIDED";
209	            case DRAFT -> throw new IllegalArgumentException("A claim cannot return to DRAFT");
210	        };
211	        if (to == ClaimStatus.SETTLED) {
212	            record(event, user, person, claim, number, " due=" + dueText(claim.getSettledDue()));
213	        } else {
214	            record(event, user, person, claim, number);
215	        }
216	        rollup.recordChanges(sheetId, user, before);
217	        return claim;
218	    }
